<table style="width:25%;margin: 0 auto;">

  <tr>

    <td><span class="teletype">OF COURSE</span></td>

    <td><a>☑</a></td>

  </tr>

  <tr>

    <td><span class="teletype">I OWE HER</span></td>

    <td><a>☑</a></td>

  </tr>

  <tr>

    <td><span class="teletype">EVERYTHING</span></td>

    <td><a>☑</a></td>

